class GenericCombinedCellOperations(GenericBts):
    """Keywords for eNB and gNB combined from different keyword types e.g. alarm and cell"""

    def __init__(self, bts_type, alarm, bbu, cell, scf, ru):
        """
        Constructor of CombinedGenericKeywords class.
        :param bts_type: GNB|ENB
        :param alarm: Object of EnbAlarm or GnbAlarm
        :param bbu: Object of EnbBbu or GnbBbu
        :param cell: Object of EnbCell or GnbCell class
        :param scf: Object of EnbScf or GnbScf class
        """
        super(GenericCombinedCellOperations, self).__init__(bts_type=bts_type)
        self.alarm = alarm
        self.bbu = bbu
        self.cell = cell
        self.scf = scf
        self.ru = ru

    @login_logout
    def lock_unlock_all_cells_for_each_group(self, bts_id=0, verify_x2_link_drop=True, du_id=0):
        """
        Locks-unlock all cells for each cell group, then locks-unlock cell group.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param verify_x2_link_drop: boolean, decides if X2 link drops will be verified when all cells are down
        :return: None
        """
        cell_group_ids = self.cell._get_all_cell_group_ids(bts_id=bts_id, du_id=du_id)

        cell_ids = list(cell_group_ids)
        for cell_group_id in cell_group_ids:
            cell_ids[cell_group_id] = (
                self.cell._get_cell_ids_in_specific_cell_group(bts_id=bts_id, cell_group_id=cell_group_id,
                                                               du_id=du_id))
        logging.info("Lock Unlock All Cells For Each Group started")
        for cell_group_id in cell_group_ids:
            logging.info("Group {} started".format(cell_group_id))
            for cell_id in cell_ids[cell_group_id]:
                logging.info("Locking/unlocking cell: {}".format(cell_id))
                self.cell.lock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                self.cell.verify_cell_is_locked(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                if len(cell_ids[cell_group_id]) == 1 and verify_x2_link_drop is True:
                    self.alarm.verify_alarm_is_active(bts_id=bts_id, fault_name="No X2 link available", du_id=du_id)
                self.cell.unlock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                if len(cell_ids[cell_group_id]) == 1 and verify_x2_link_drop is True:
                    self.bbu.wait_for_site_to_be_onair(bts_id=bts_id, timeout=480, interval=10)
                    self.alarm.verify_alarm_is_not_active(bts_id=bts_id, fault_name="No X2 link available",
                                                          du_id=du_id)
                self.cell.wait_for_cell_to_be_onair(bts_id=bts_id, cell_id=cell_id, du_id=du_id)

            logging.info("Locking cell group : {}".format(cell_group_id))
            self.cell.lock_cell_group_via_gui(bts_id=bts_id, cell_group_id=cell_group_id, du_id=du_id)
            if len(cell_group_ids) == 1 and verify_x2_link_drop is True:
                time.sleep(75)
                self.alarm.verify_alarm_is_active(bts_id=bts_id, fault_name="No X2 link available", du_id=du_id)
            logging.info("Unlocking cell group : {}".format(cell_group_id))
            self.cell.unlock_cell_group_via_gui(bts_id=bts_id, cell_group_id=cell_group_id, du_id=du_id)
            if len(cell_group_ids) == 1 and verify_x2_link_drop is True:
                self.bbu.wait_for_site_to_be_onair(bts_id=bts_id, timeout=480, interval=10)
                self.alarm.verify_alarm_is_not_active(bts_id=bts_id, fault_name="No X2 link available", du_id=du_id)
            logging.info("Group {} ended".format(cell_group_id))

    @login_logout
    def lock_all_cells_and_then_unlock_for_each_group(self, bts_id=0, verify_x2_link_drop=True, du_id=0):
        """
        Locks all cells for each cell group, then unlocks them all back.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param verify_x2_link_drop: boolean, decides if X2 link drops will be verified when all cells are down
        :return: None
        """
        cell_group_ids = self.cell._get_all_cell_group_ids(bts_id=bts_id, du_id=du_id)

        cell_ids = list(cell_group_ids)
        for cell_group_id in cell_group_ids:
            cell_ids[cell_group_id] = (
                self.cell._get_cell_ids_in_specific_cell_group(bts_id=bts_id, cell_group_id=cell_group_id,
                                                               du_id=du_id))
        logging.info("Lock All Cells And Then Unlock For Each Group started")
        for cell_group_id in cell_group_ids:
            logging.info("Group {} started".format(cell_group_id))
            for cell_id in cell_ids[cell_group_id]:
                logging.info("Locking cell: {}".format(cell_id))
                self.cell.lock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                self.cell.verify_cell_is_locked(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            if len(cell_group_ids) == 1 and verify_x2_link_drop is True:
                time.sleep(75)
                self.alarm.verify_alarm_is_active(bts_id=bts_id, fault_name="No X2 link available", du_id=du_id)
                x2_link_down = True
            for cell_id in cell_ids[cell_group_id]:
                logging.info("Unlocking cell: {}".format(cell_id))
                self.cell.unlock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                if len(cell_group_ids) == 1 and verify_x2_link_drop is True and x2_link_down is True:
                    self.bbu.wait_for_site_to_be_onair(bts_id=bts_id, timeout=480, interval=10)
                    self.alarm.verify_alarm_is_not_active(bts_id=bts_id, fault_name="No X2 link available",
                                                          du_id=du_id)
                    x2_link_down = False
                self.cell.wait_for_cell_to_be_onair(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            logging.info("Group {} ended".format(cell_group_id))

    @login_logout
    def lock_all_cell_groups_and_then_unlock(self, bts_id=0, verify_x2_link_drop=True, du_id=0):
        """
        Locks all cell groups, then unlock them back.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param verify_x2_link_drop: boolean, decides if X2 link drops will be verified when all cells are down
        :return: None
        """
        cell_group_ids = self.cell._get_all_cell_group_ids(bts_id=bts_id, du_id=du_id)

        logging.info("Lock All Cell Groups And Then Unlock started")
        for cell_group_id in cell_group_ids:
            logging.info("Locking cell group : {}".format(cell_group_id))
            self.cell.lock_cell_group_via_gui(bts_id=bts_id, cell_group_id=cell_group_id, du_id=du_id)
        if verify_x2_link_drop is True:
            time.sleep(75)
            self.alarm.verify_alarm_is_active(bts_id=bts_id, fault_name="No X2 link available", du_id=du_id)
        for cell_group_id in cell_group_ids:
            logging.info("Unlocking cell group : {}".format(cell_group_id))
            self.cell.unlock_cell_group_via_gui(bts_id=bts_id, cell_group_id=cell_group_id, du_id=du_id)
        if verify_x2_link_drop is True:
            self.bbu.wait_for_site_to_be_onair(bts_id=bts_id, timeout=480, interval=10)
            self.alarm.verify_alarm_is_not_active(bts_id=bts_id, fault_name="No X2 link available", du_id=du_id)

    @login_logout
    def block_unblock_all_cells_for_each_group(self, bts_id=0, verify_x2_link_drop=True, du_id=0):
        """
        Blocks-unblock all cells for each cell group, then blocks-unblock cell group.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param verify_x2_link_drop: boolean, decides if X2 link drops will be verified when all cells are down
        :return: None
        """

        cell_group_ids = self.cell._get_all_cell_group_ids(bts_id=bts_id, du_id=du_id)
        cell_ids = dict.fromkeys(list(cell_group_ids))
        for cell_group_id in cell_group_ids:
            cell_ids[cell_group_id] = (
                self.cell._get_cell_ids_in_specific_cell_group(bts_id=bts_id, cell_group_id=cell_group_id,
                                                               du_id=du_id))
        logging.info("Lock Unlock All Cells For Each Group started")
        for cell_group_id in cell_group_ids:
            logging.info("Group {} started".format(cell_group_id))
            for cell_id in cell_ids[cell_group_id]:
                logging.info("Blocking/unblocking cell: {}".format(cell_id))
                self.cell.block_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                self.cell.verify_cell_is_blocked(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                self.cell.unblock_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                self.cell.wait_for_cell_to_be_onair(bts_id=bts_id, cell_id=cell_id, du_id=du_id)

    @login_logout
    def block_all_cells_and_then_unblock_one_by_one(self, bts_id=0, verify_x2_link_drop=True, du_id=0):
        """
        Blocks all cells one by one, then unlbocks them all back.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param verify_x2_link_drop: boolean, decides if X2 link drops will be verified when all cells are down
        :return: None
        """
        cells_ids = self.cell._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
        cells_ids_rand = random.sample(cells_ids, len(cells_ids))
        for cell_id in cells_ids_rand:
            logging.info("Blocking cell: {}".format(cell_id))
            self.cell.block_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            self.cell.verify_cell_is_blocked(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            logging.info("Unblocking cell: {}".format(cell_id))
            self.cell.unblock_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            self.cell.wait_for_cell_to_be_onair(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
        logging.info("All cells unblocking {} ended")

    @login_logout
    def remove_cell_from_configuration(self, cell_id, bts_id=0, cell_group_id=0, du_id=0, power_group_id=1,
                                       power_saving_cell_list=None):
        """
        Removes cell with given id from configuration. Supports removal of more than one cell.
        :param cell_id: id of cell that will be removed as string or multiple ids as list of strings.
        :param cell_group_id: group id of removed cell(s); removal of cells from different groups is not supported!
        :param bts_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        bts_build_raw = self.bbu.get_bts_sw_version(bts_id=bts_id, du_id=du_id)
        bts_build = SbtsSwVersion(bts_build_raw)
        release_24r2_or_newer = True if bts_build >= SbtsSwVersion('SBTS24R2_ENB_0000_000000_000000') else False

        mrbts_id = self.get_bts_instance_id(bts_id=bts_id, du_id=du_id)
        dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
        cell_ids_in_group = self.cell._get_cell_ids_in_specific_cell_group(bts_id=bts_id,
                                                                           du_id=du_id,
                                                                           cell_group_id=cell_group_id)
        cells_ids_to_remove = cell_id if isinstance(cell_id, list) else [cell_id]
        new_cell_ids = [cell_id_in_group for cell_id_in_group in cell_ids_in_group
                        if str(cell_id_in_group) not in cells_ids_to_remove]

        max_num_of_cells = abs(len(new_cell_ids) - len(cells_ids_to_remove))
        max_num_cell_value = max_num_of_cells if max_num_of_cells in range(1, 8) else 3
        delta = [
            {
                'distName': "{}/NRCELLGRP-{}".format(dist_name, cell_group_id),
                'operation': 'update',
                'parameters': [{
                    'operation': 'update',
                    'parameterName': 'nrCellList',
                    'value': new_cell_ids
                }]
            },
            {
                'distName': dist_name,
                'operation': 'update',
                'parameters': [{
                    'operation': 'update',
                    'parameterName': 'maxNumScellsDl',
                    'value': max_num_cell_value
                }]
            },
        ]

        cells_tdd = self.cell.get_tdd_cells_info(bts_id=bts_id, du_id=du_id)
        if release_24r2_or_newer and len(cells_tdd) >= 8 and max_num_of_cells != 8:
            delta.extend([
                {
                    'distName': dist_name,
                    'operation': 'update',
                    'parameters': [{
                        'operation': 'update',
                        'parameterName': 'actFr2L2DlTdMetricPreCalc8CC',
                        'value': 'false'
                    }]
                }])

        for single_cell_id in cells_ids_to_remove:
            delta.extend([
                {
                    'distName': '{}/NRCELL-{}'.format(dist_name, single_cell_id),
                    'operation': 'delete',
                    'parameters': []
                },
                {
                    'distName': 'MRBTS-{}/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-{}'.format(mrbts_id, single_cell_id),
                    'operation': 'delete',
                    'parameters': []
                }])

        if power_saving_cell_list:
            delta_power_saving_cell_list = [item for item in power_saving_cell_list if item['nrCellId'] not in
                                            cells_ids_to_remove]
            logging.debug(f'Delta power saving cell list: {delta_power_saving_cell_list}')
            delta.extend([
                {
                    'distName': f'{dist_name}/NRPGRP-{power_group_id}',
                    'operation': 'update',
                    'parameters': [{
                        'operation': 'update',
                        'parameterName': 'lbpsCellList',
                        'value': delta_power_saving_cell_list
                    }]
                }])
        logging.debug(f'Removing cell(s) from configuration - delta:\n{delta}')
        self.scf.perform_bts_delta_commissioning(delta=delta)

    def get_power_saving_cell_list(self, power_group_id=1, bts_id=0, du_id=0):
        dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
        power_saving_cell_group_distname = f"{dist_name}/NRPGRP-{power_group_id}"
        nrpgrp_class_content = self.scf.get_all_params_under_class_name(class_name="com.nokia.srbts.nrbts:NRPGRP")
        for item in nrpgrp_class_content:
            if item['dist_name'] == power_saving_cell_group_distname:
                power_saving_cell_list = item["params"]["lbpsCellList"]
                logging.debug(f"Power saving cell list: {power_saving_cell_list}")
                return power_saving_cell_list
        raise ValueError(f'Unable to find item with distName={power_saving_cell_group_distname} '
                         f'inside com.nokia.srbts.nrbts:NRPGRP class content:\n{nrpgrp_class_content}\n')

    @login_logout
    def add_new_cell_based_on_existing_cell_to_configuration(self, cell_parameters,
                                                             cell_id_to_copy_from,
                                                             nrcell_include_subobject=False,
                                                             activate_plan_despite_errors=False,
                                                             group_id=0,
                                                             bts_id=0,
                                                             du_id=0,
                                                             power_group_id=1,
                                                             power_saving_cell_list=None):
        """
        Adds a new cell to configuration based on an existing cell
        [Support only NRCELL]

        :param cell_parameters:          dictionary containing values for mandatory parameters:
                                         lcrId, nrarfcn, gscn, physCellId
                                            example:
                                            cell_parameters =[{
                                                'lcrId': '4',
                                                'nrarfcn': '2103311',
                                                'gscn': '22558',
                                                'physCellId': '44'
                                            }]
        :param cell_id_to_copy_from:     id of cell that new cell will be based on
        :param group_id:                 group id of copied cell
        :param nrcell_include_subobject: whether include subobjects when add NRCELL object
        :param activate_plan_despite_errors    activate plan despite errors when do activation, by default is False
        :param bts_id:                   gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        bts_build_raw = self.bbu.get_bts_sw_version(bts_id=bts_id, du_id=du_id)
        bts_build = SbtsSwVersion(bts_build_raw)
        release_24r2_or_newer = True if bts_build >= SbtsSwVersion('SBTS24R2_ENB_0000_000000_000000') else False

        cell_configuration = self.cell.copy_existing_cell_configuration(cell_parameters, group_id, bts_id, du_id)
        self.cell._add_new_cell_based_on_existing_cell_to_configuration_via_gui(
            cell_id_to_copy_from,
            cell_configuration['cell_id'],
            cell_configuration['nrarfcn'],
            cell_configuration['gscn'],
            cell_configuration['physCellId'],
            cell_configuration['type0CoresetConfigurationIndex'],
            cell_configuration['maxNumScellsDl'],
            cell_configuration['dist_name'],
            cell_configuration['cell_dist_name'],
            cell_configuration['cell_group_dist_name'],
            cell_configuration['mrbts_id'],
            cell_configuration['cell_ids_in_group'],
            nrcell_include_subobject,
            activate_plan_despite_errors,
            bts_id,
            du_id,
            cell_configuration['gscn_filter_param'])

        if power_saving_cell_list:
            dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
            delta = [
                {
                    'distName': f'{dist_name}/NRPGRP-{power_group_id}',
                    'operation': 'update',
                    'parameters': [{
                        'operation': 'update',
                        'parameterName': 'lbpsCellList',
                        'value': power_saving_cell_list
                    }]
                }]

            cells_tdd = self.cell.get_tdd_cells_info(bts_id=bts_id, du_id=du_id)
            if release_24r2_or_newer and len(cells_tdd) >= 8 and len(
                    self.cell.get_all_cells_id(bts_id=bts_id, du_id=du_id)) == 8:
                delta.extend([
                    {
                        'distName': dist_name,
                        'operation': 'update',
                        'parameters': [{
                            'operation': 'update',
                            'parameterName': 'actFr2L2DlTdMetricPreCalc8CC',
                            'value': 'true'
                        }]
                    }])
            logging.debug(f'Adding cell to configuration - adjustment delta:\n{delta}')
            self.scf.perform_bts_delta_commissioning(delta=delta)

    @login_logout
    def remove_fr1_cell_and_nrcellgrp_from_configuration(self, cell_id, cell_group_id, bts_id=0, du_id=0):
        """
        Removes cell with given id from configuration.
        :param cell_id:     id of cell that will be removed
        :param cell_group_id:            group id of removed cell that will be removed
        :param bts_id:                   gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
        group_ids_in_nrdu = self.cell._get_all_cell_group_ids(bts_id=bts_id, du_id=du_id)
        new_group_ids = []
        for group_id_in_nrdu in group_ids_in_nrdu:
            if group_id_in_nrdu != int(cell_group_id):
                new_group_ids.append(str(group_id_in_nrdu))
        mrbts_id = self.get_bts_instance_id(bts_id=bts_id, du_id=du_id)
        delta = [{
            'distName': dist_name + "/NRCELL-" + str(cell_id),
            'operation': 'delete',
            'parameters': []
        }, {
            'distName': dist_name + "/NRCELLGRP-" + str(cell_group_id),
            'operation': 'delete',
            'parameters': []
        }, {
            'distName': "MRBTS-" + str(mrbts_id) + "/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-" + str(cell_id),
            'operation': 'delete',
            'parameters': []
        }, {
            'distName': "MRBTS-" + str(mrbts_id) + "/NRBTS-" + str(mrbts_id) + "/NRDU-1",
            'operation': 'update',
            'parameters': [{
                'operation': 'update',
                'parameterName': 'refNrCellGroup',
                'value': new_group_ids
            }]
        }]

        self.scf.perform_bts_delta_commissioning(delta=delta)

    @login_logout
    def _set_x2_link_to(self, parameter, value, bts_id=0, du_id=0):
        """
        Set parameter and value for eNB or gNB.
        :param bts_id: ID of eNB/gNB
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param parameter: parameter to be changed - administrativeState for eNB, x2LinkLock for gNB
        :param value: action to be performed, either 'locked' or 'unlocked'
        :return: None.
        """
        dist_name = self.patterns.x2_link_dist_name.format(self.get_bts_instance_id(bts_id, du_id),
                                                           self.get_global_bts_id(bts_id, du_id))

        self.scf.perform_parameter_recommissioning(dist_name, parameter, 'update', value,
                                                   skip_parameter_relation_errors=False, should_activate=True,
                                                   timeout=60, bts_id=bts_id, du_id=du_id)

    @login_logout_GUI
    def add_extension_panel_and_configure_proper_beamset_via_gui(self, number_of_extenders, prodCodePlanned,
                                                                 first_rmod_id, second_rmod_id, loglinkId,
                                                                 basicBeamSet, cell_id=None, bts_id=0, du_id=0):
        """
        Configure extension panel or panels and set proper beamset values for given configuration.
        :param number_of_extenders:      number of extenders to configure
        :param prodCodePlanned:          value of prodCodePlanned parameter of extension panel
        :param first_rmod_id:            id of existing RMOD corresponding to radio unit
        :param second_rmod_id:           id of new RMOD corresponding to extension panel
        :param loglink_id:               id of the new loglink
        :param basicBeamSet              dict with beam set and angles e.g.
                                         basicBeamSet = {
                                        "Basic Beam Set": "beamSetFR2_6_6_4_2P",
                                        "Left Cell Edge Angle": "90",
                                        "Lower Cell Edge Angle": "110",
                                        "Right Cell Edge Angle": "90",
                                        "Upper Cell Edge Angle": "90"
                                        }
        :param cell_id                  cell id value - set to None to configure beam sets for all cells
        :param bts_id:                  bts id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """

        for index in range(number_of_extenders):
            second_rmod_id += index
            loglinkId += index
            loglinkName = "EXTMOD-{}".format(index + 1)
            self.ru._add_new_ru_based_on_existing_ru_to_configuration_via_gui(prodCodePlanned, first_rmod_id,
                                                                              second_rmod_id, bts_id=bts_id,
                                                                              du_id=du_id)
            self.ru._add_new_loglink_via_gui(loglinkId, loglinkName, first_rmod_id, second_rmod_id, bts_id=bts_id,
                                             du_id=du_id)

        self.cell._set_new_beamset_value_via_gui(basicBeamSet, cell_id=cell_id, bts_id=bts_id, du_id=du_id)
        self.gui_coam.activate_plan(sbts=self.gui_alias.format(bts_id, du_id))


@six.add_metaclass(Singleton)
class EnbCombinedCellOperations(GenericCombinedCellOperations):
    """Class contains keywords for eNB combined from different keyword types e.g. alarm and cell"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.
        """

        super(EnbCombinedCellOperations, self).__init__(bts_type=EnbCombinedCellOperations.bts_type,
                                                        alarm=EnbAlarmVerification(),
                                                        bbu=EnbDuOperations(),
                                                        cell=EnbCellOperations(),
                                                        scf=EnbCommissioning(),
                                                        ru=EnbRuOperations())

    def unlock_x2_link(self, enb_id=0, du_id=0):
        """
        Unlock x2 link on eNB.
        :param enb_id: ID of eNB
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None.
        """
        self._set_x2_link_to(bts_id=enb_id, du_id=du_id, parameter='administrativeState', value='unlocked')

    def lock_x2_link(self, enb_id=0, du_id=0):
        """
        Unlock x2 link on eNB.
        :param enb_id: ID of eNB
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None.
        """
        self._set_x2_link_to(bts_id=enb_id, du_id=du_id, parameter='administrativeState', value='locked')


